(function(){
let reportHTML='',selection={};const css=document.querySelector('link[href^="style.css"]').href;
function options(){const opts={members:[...document.querySelectorAll('[data-report-member]:checked')].map(t=>Number(t.dataset.reportMember))};RiskReport.definitions.forEach(([k])=>opts[k]=$('reportOpt_'+k).checked);return opts;}
function refresh(){try{reportHTML=RiskReport.build(family,options(),$('date').value,Number($('drop').value)/100);$('clientReportContent').innerHTML=reportHTML;$('reportOptionError').textContent='';$('printClientReport').disabled=$('downloadClientReport').disabled=false;}catch(e){reportHTML='';$('clientReportContent').innerHTML='';$('reportOptionError').textContent=e.message;$('printClientReport').disabled=$('downloadClientReport').disabled=true;}}
function open(){selection=Object.fromEntries(RiskReport.definitions.map(([k,n,on])=>[k,on]));$('reportOptions').innerHTML=`<div class="reportSelections"><div><strong>成員</strong><div class="reportChecks">${family.map((m,i)=>`<label><input type="checkbox" data-report-member="${i}" checked>${esc(m.name)}</label>`).join('')}</div></div><div><strong>報告內容</strong><div class="reportChecks">${RiskReport.definitions.map(([k,n,on])=>`<label><input id="reportOpt_${k}" type="checkbox" data-report-section="${k}" ${on?'checked':''}>${n}</label>`).join('')}</div></div></div>`;refresh();$('clientReportDialog').showModal();}
$('reportOptions').addEventListener('change',refresh);$('dashboardReport').onclick=open;$('closeClientReport').onclick=()=>{document.body.classList.remove('printingClient');$('clientReportDialog').close();};$('printClientReport').onclick=()=>{document.body.classList.add('printingClient');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('printingClient'));
$('downloadClientReport').onclick=()=>{if(!reportHTML)return;const html='<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>家族資產與風險報告</title><style>'+window.RiskReportStyle+'</style></head><body class="standaloneReport"><button class="standalonePrint" onclick="window.print()">列印／存成 PDF</button>'+reportHTML+'</body></html>',url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='family-risk-report-'+($('date').value||'snapshot')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
})();
